    func put(_ key: Int, _ value: Int, ttlSeconds: Double) {
        if store[key] == nil, store.count >= capacity {
            let oldest = order.removeFirst()
            store.removeValue(forKey: oldest)
        }
        store[key] = Entry(value: value, expiresAt: now() + ttlSeconds)
        touch(key)
    }

    private func touch(_ key: Int) {
        order.removeAll { $0 == key }
        order.append(key)
    }
