func minWindowSubstring(_ s: String, _ t: String) -> String {
    guard !s.isEmpty, !t.isEmpty else { return "" }
    var required: [Character: Int] = [:]
    for char in t {
        required[char, default: 0] += 1
    }
    var missing = t.count
    var left = s.startIndex
    var bestStart = s.startIndex
    var bestLength = Int.max
    var i = s.startIndex
    while i != s.endIndex {
        let char = s[i]
        if let count = required[char] {
            if count > 0 {
                missing -= 1
            }
            required[char] = count - 1
        }
        while missing == 0 {
            let currentLength = s.distance(from: left, to: i) + 1
            if currentLength < bestLength {
                bestLength = currentLength
                bestStart = left
            }
            let leftChar = s[left]
            if let count = required[leftChar] {
                required[leftChar] = count + 1
                if count + 1 > 0 {
                    missing += 1
                }
            }
            left = s.index(after: left)
        }
        i = s.index(after: i)
    }
    guard bestLength != Int.max else { return "" }
    let endIndex = s.index(bestStart, offsetBy: bestLength)
    return String(s[bestStart..<endIndex])
