    for node in graph.keys { state[node] = .unvisited }
    var stack: [Int] = []
    var cycleNodes: Set<Int> = []
    var postOrder: [Int] = []

    func dfs(_ node: Int) {
        state[node] = .visiting
        stack.append(node)
        for neighbor in graph[node] ?? [] {
            switch state[neighbor, default: .unvisited] {
            case .unvisited:
                dfs(neighbor)
            case .visiting:
                if let ancestorIndex = stack.firstIndex(of: neighbor) {
                    for n in stack[ancestorIndex...] { cycleNodes.insert(n) }
                }
            case .visited:
                break
            }
        }
        stack.removeLast()
        state[node] = .visited
        postOrder.append(node)
    }

    for node in graph.keys {
        if state[node] == .unvisited {
            dfs(node)
        }
    }

    if cycleNodes.isEmpty {
        return TopoResult(order: postOrder.reversed().map { $0 }, cycleNodes: [])
    }
    return TopoResult(order: nil, cycleNodes: cycleNodes.sorted())
}

