data class TopoResult(val order: List<Int>?, val cycleNodes: List<Int>)

fun topologicalOrderWithCycles(graph: Map<Int, List<Int>>): TopoResult {
    enum class State { UNVISITED, VISITING, VISITED }
    val state = HashMap<Int, State>()
    for (node in graph.keys) state[node] = State.UNVISITED
    val stack = mutableListOf<Int>()
    val cycleNodes = mutableSetOf<Int>()
    val postOrder = mutableListOf<Int>()

    fun dfs(node: Int) {
        state[node] = State.VISITING
        stack.add(node)
        for (neighbor in graph[node].orEmpty()) {
            when (state[neighbor] ?: State.UNVISITED) {
                State.UNVISITED -> dfs(neighbor)
                State.VISITING -> {
                    val ancestorIndex = stack.indexOf(neighbor)
                    if (ancestorIndex != -1) {
                        cycleNodes.addAll(stack.subList(ancestorIndex, stack.size))
                    }
                }
                State.VISITED -> {}
            }
        }
        stack.removeAt(stack.size - 1)
        state[node] = State.VISITED
        postOrder.add(node)
    }

    for (node in graph.keys) {
        if (state[node] == State.UNVISITED) {
            dfs(node)
        }
    }

    return if (cycleNodes.isEmpty()) {
        TopoResult(postOrder.reversed(), emptyList())
    } else {
        TopoResult(null, cycleNodes.sorted())
    }
}

