func groupAnagrams(_ words: [String]) -> [[String]] {
    var groups: [String: [String]] = [:]
    for word in words {
        let key = frequencySignature(word)
        groups[key, default: []].append(word)
    }
    return Array(groups.values)
}

private func frequencySignature(_ word: String) -> String {
    var counts = [Int](repeating: 0, count: 26)
    let base = Character("a").asciiValue!
    for char in word {
        if let value = char.asciiValue, value >= base, value < base + 26 {
            counts[Int(value - base)] += 1
        }
    }
    return counts.map(String.init).joined(separator: ",")
}

