        groups.getOrPut(key) { mutableListOf() }.add(word)
    }
    return groups.values.toList()
}

private fun frequencySignature(word: String): String {
    val counts = IntArray(26)
    for (c in word) {
        val index = c - 'a'
        if (index in 0..25) counts[index]++
    }
    return counts.joinToString(",")
}

