func findAnagramStartIndices(_ text: String, _ pattern: String) -> [Int] {
    let textChars = Array(text)
    let patternChars = Array(pattern)
    let windowSize = patternChars.count
    guard windowSize > 0, textChars.count >= windowSize else { return [] }

    var patternCounts: [Character: Int] = [:]
    for char in patternChars {
        patternCounts[char, default: 0] += 1
    }

    var windowCounts: [Character: Int] = [:]
    var results: [Int] = []

    for i in 0..<textChars.count {
        let incoming = textChars[i]
        windowCounts[incoming, default: 0] += 1

        let outgoingIndex = i - windowSize
        if outgoingIndex >= 0 {
            let outgoing = textChars[outgoingIndex]
            windowCounts[outgoing]! -= 1
            if windowCounts[outgoing] == 0 {
                windowCounts.removeValue(forKey: outgoing)
            }
        }

        if i >= windowSize - 1, windowCounts == patternCounts {
            results.append(i - windowSize + 1)
        }
    }
    return results
}

