fun findAnagramStartIndices(text: String, pattern: String): List<Int> {
    val windowSize = pattern.length
    if (windowSize == 0 || text.length < windowSize) return emptyList()

    val patternCounts = HashMap<Char, Int>()
    for (c in pattern) {
        patternCounts[c] = (patternCounts[c] ?: 0) + 1
    }

    val windowCounts = HashMap<Char, Int>()
    val results = mutableListOf<Int>()

    for (i in text.indices) {
        val incoming = text[i]
        windowCounts[incoming] = (windowCounts[incoming] ?: 0) + 1

        val outgoingIndex = i - windowSize
        if (outgoingIndex >= 0) {
            val outgoing = text[outgoingIndex]
            val newCount = windowCounts.getValue(outgoing) - 1
            if (newCount == 0) {
                windowCounts.remove(outgoing)
            } else {
                windowCounts[outgoing] = newCount
            }
        }

        if (i >= windowSize - 1 && windowCounts == patternCounts) {
            results.add(i - windowSize + 1)
        }
    }
    return results
}

